SELECT CASE WHEN r.name = 'Dhaka' THEN 'Dhaka' ELSE 'Other divisions' END AS area, AVG(CASE WHEN p.method = 'cod' THEN 1.0 ELSE 0.0 END) AS cod_share FROM orders o JOIN payments p ON p.order_id = o.order_id AND p.status = 'captured' JOIN customer_addresses a ON a.address_id = o.address_id JOIN cities ci ON ci.city_id = a.city_id JOIN regions r ON r.region_id = ci.region_id WHERE NOT o.is_deleted AND CAST(o.order_at AS DATE) BETWEEN DATE '2024-01-01' AND DATE '2024-12-31' GROUP BY 1
